package com.ddtracker;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class DdTrackerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(DdTrackerPlugin.class);
		RuneLite.main(args);
	}
}

package com.ddtracker;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

public class DdTrackerOverlay extends Overlay
{
	private static final Stroke GATE_STROKE = new BasicStroke(2f);
	private static final int GATE_OUTLINE_WIDTH = 3;
	private static final int GATE_OUTLINE_FEATHER = 4;

	private final Client client;
	private final DdTrackerPlugin plugin;
	private final DdTrackerConfig config;
	private final ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	private DdTrackerOverlay(Client client, DdTrackerPlugin plugin, DdTrackerConfig config,
		ModelOutlineRenderer modelOutlineRenderer)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.modelOutlineRenderer = modelOutlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		renderBankGates(graphics);
		renderGearWarnings(graphics);
		renderCallout(graphics);
		renderDd(graphics);
		return null;
	}

	// ---- DD tile + call ----

	private void renderDd(Graphics2D graphics)
	{
		final WorldPoint tile = plugin.getDdTile();
		if (tile == null || tile.getPlane() != client.getPlane())
		{
			return;
		}

		final LocalPoint lp = LocalPoint.fromWorld(client, tile);
		if (lp != null)
		{
			final Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly != null)
			{
				OverlayUtil.renderPolygon(graphics, poly, config.tileColor());
			}
		}

		final DdCall call = plugin.getActiveCall();
		if (call == null)
		{
			return;
		}

		if (!call.isFinished())
		{
			renderActiveCall(graphics, call, lp);
		}
		else if (lp != null)
		{
			final String txt = call.getCompliedCount() + "/" + call.getTracked().size() + " DD'd";
			renderTileText(graphics, lp, txt, Color.WHITE);
		}
	}

	private void renderActiveCall(Graphics2D graphics, DdCall call, LocalPoint lp)
	{
		if (lp != null)
		{
			// Deliberately not a countdown: the call runs until someone clears it, so the
			// useful number over the tile is how many are actually on it.
			renderTileText(graphics, lp,
				"DD  " + call.getCompliedCount() + "/" + call.getTracked().size(),
				Color.WHITE);
		}

		for (Player p : client.getPlayers())
		{
			if (p == null || p.getName() == null)
			{
				continue;
			}
			final DdCall.TrackedPlayer tp = call.getTracked().get(DdTrackerPlugin.normalize(p.getName()));
			if (tp == null)
			{
				continue;
			}

			final Color color;
			if (plugin.isOnDdTile(p))
			{
				color = config.onTileColor();
			}
			else if (tp.complied)
			{
				color = config.compliedColor();
			}
			else
			{
				color = config.offTileColor();
			}

			final Polygon poly = p.getCanvasTilePoly();
			if (poly != null)
			{
				OverlayUtil.renderPolygon(graphics, poly, color);
			}

			final String name = p.getName();
			final Point textLoc = p.getCanvasTextLocation(graphics, name, p.getLogicalHeight() + 40);
			if (textLoc != null)
			{
				OverlayUtil.renderTextLocation(graphics, textLoc, name, color);
			}
		}
	}

	// ---- Mass bank gates ----

	private void renderBankGates(Graphics2D graphics)
	{
		final String label = plugin.getBankAlertLabel();
		if (label == null || !config.massBankReminder())
		{
			return;
		}

		final Color color = config.massBankColor();
		final Color fill = new Color(color.getRed(), color.getGreen(), color.getBlue(), 40);
		final Player local = client.getLocalPlayer();

		TileObject nearest = null;
		int nearestDistance = Integer.MAX_VALUE;

		for (TileObject gate : plugin.getBankGates())
		{
			if (gate.getPlane() != client.getPlane())
			{
				continue;
			}

			modelOutlineRenderer.drawOutline(gate, GATE_OUTLINE_WIDTH, color, GATE_OUTLINE_FEATHER);

			final Shape clickbox = gate.getClickbox();
			if (clickbox != null)
			{
				OverlayUtil.renderPolygon(graphics, clickbox, color, fill, GATE_STROKE);
			}

			if (local != null)
			{
				final WorldPoint wp = gate.getWorldLocation();
				if (wp != null)
				{
					final int distance = local.getWorldLocation().distanceTo(wp);
					if (distance < nearestDistance)
					{
						nearestDistance = distance;
						nearest = gate;
					}
				}
			}
		}

		// One label only, on the closest gate, so a double gate is not written on twice.
		// No countdown here on purpose - the gates just stay gold until the timer lapses.
		if (nearest != null)
		{
			final LocalPoint lp = nearest.getLocalLocation();
			if (lp != null)
			{
				renderTileText(graphics, lp, label, color);
			}
		}
	}

	// ---- Location callout ----

	private void renderCallout(Graphics2D graphics)
	{
		final WorldPoint wp = plugin.getCalloutPoint();
		if (wp == null || wp.getPlane() != client.getPlane())
		{
			return;
		}

		final LocalPoint lp = LocalPoint.fromWorld(client, wp);
		if (lp == null)
		{
			// Off-scene: the hint arrow (minimap + edge of screen) still points there
			return;
		}

		final Polygon area = Perspective.getCanvasTileAreaPoly(client, lp, 3);
		if (area != null)
		{
			OverlayUtil.renderPolygon(graphics, area, config.calloutColor());
		}

		final int ticksLeft = Math.max(0, plugin.getCalloutEndTick() - client.getTickCount());
		final int secsLeft = (int) Math.ceil(ticksLeft * 0.6);
		final String label = plugin.getCalloutLabel() + " (" + secsLeft + "s)";
		renderTileText(graphics, lp, label, config.calloutColor());
	}

	// ---- Gear check ----

	private void renderGearWarnings(Graphics2D graphics)
	{
		if (config.gearCheck() == DdTrackerConfig.GearCheckMode.OFF && !config.armourCheck())
		{
			return;
		}

		for (Player p : client.getPlayers())
		{
			if (p == null || p.getName() == null)
			{
				continue;
			}
			final String warning = plugin.gearWarning(p);
			if (warning == null)
			{
				continue;
			}
			final Color color = plugin.isNakedWarning(warning)
				? config.nakedWarnColor()
				: config.gearWarnColor();
			final Point loc = p.getCanvasTextLocation(graphics, warning, p.getLogicalHeight() + 90);
			if (loc != null)
			{
				OverlayUtil.renderTextLocation(graphics, loc, warning, color);
			}
		}
	}

	private void renderTileText(Graphics2D graphics, LocalPoint lp, String text, Color color)
	{
		final Point pt = Perspective.getCanvasTextLocation(client, graphics, lp, text, 0);
		if (pt != null)
		{
			OverlayUtil.renderTextLocation(graphics, pt, text, color);
		}
	}
}

package com.ddtracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Comparator;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

public class DdTrackerPanel extends PluginPanel
{
	private final JLabel statusLabel = new JLabel();
	private final JLabel callHeader = new JLabel();
	private final JPanel callPanel = new JPanel();
	private final JLabel gearHeader = new JLabel();
	private final JPanel gearPanel = new JPanel();
	private final JPanel listPanel = new JPanel();

	DdTrackerPanel(DdTrackerPlugin plugin)
	{
		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		final JPanel header = new JPanel(new BorderLayout(0, 4));
		header.setOpaque(false);

		final JLabel title = new JLabel("Wildy Agility");
		title.setFont(title.getFont().deriveFont(Font.BOLD, 16f));
		title.setForeground(Color.WHITE);
		header.add(title, BorderLayout.NORTH);

		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		header.add(statusLabel, BorderLayout.CENTER);

		final JButton resetButton = new JButton("Reset stats");
		resetButton.addActionListener(e -> plugin.requestResetStats());
		header.add(resetButton, BorderLayout.SOUTH);

		add(header, BorderLayout.NORTH);

		// Gear first: it is live "who is a problem right now", where the compliance list
		// below it is history you read after the fact.
		final JPanel body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setOpaque(false);

		callPanel.setLayout(new BoxLayout(callPanel, BoxLayout.Y_AXIS));
		callPanel.setOpaque(false);
		callPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

		gearPanel.setLayout(new BoxLayout(gearPanel, BoxLayout.Y_AXIS));
		gearPanel.setOpaque(false);
		gearPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

		listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
		listPanel.setOpaque(false);
		listPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

		// Live call first: while one is running it is the only thing you care about.
		body.add(sectionHeader(callHeader, "DD CALL"));
		body.add(callPanel);
		body.add(Box.createVerticalStrut(12));
		body.add(sectionHeader(gearHeader, "GEAR CHECK"));
		body.add(gearPanel);
		body.add(Box.createVerticalStrut(12));
		body.add(sectionHeader(new JLabel(), "DD COMPLIANCE"));
		body.add(listPanel);

		add(body, BorderLayout.CENTER);
		add(buildCommunityFooter(), BorderLayout.SOUTH);

		updateGear(java.util.Collections.emptyList());
		updateCall(null);
	}

	private JLabel sectionHeader(JLabel label, String text)
	{
		label.setText(text);
		label.setFont(label.getFont().deriveFont(Font.BOLD, 11f));
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		return label;
	}

	private JPanel buildCommunityFooter()
	{
		final JPanel footer = new JPanel();
		footer.setLayout(new BoxLayout(footer, BoxLayout.Y_AXIS));
		footer.setOpaque(false);
		footer.setBorder(BorderFactory.createEmptyBorder(10, 0, 0, 0));

		final JLabel fcLabel = new JLabel("In game: join FC \"Agility FC\"");
		fcLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		fcLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		footer.add(fcLabel);

		final JLabel discordLabel = new JLabel("Discord: discord.gg/agilityfc");
		discordLabel.setForeground(ColorScheme.BRAND_ORANGE);
		discordLabel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		discordLabel.setToolTipText("Open the Agility FC Discord invite in your browser");
		discordLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		discordLabel.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				LinkBrowser.browse("https://discord.gg/agilityfc");
			}
		});
		footer.add(discordLabel);

		return footer;
	}

	// ---- Live DD call ----

	void updateCall(DdStatus status)
	{
		SwingUtilities.invokeLater(() ->
		{
			callPanel.removeAll();

			if (status == null)
			{
				callHeader.setText("DD CALL");
				callPanel.add(hint("No call running."));
			}
			else
			{
				callHeader.setText("DD CALL — " + status.getOnTile().size()
					+ " / " + status.getTracked() + " stacked");

				final JLabel meta = hint(status.getElapsedSeconds() + "s · called by "
					+ status.getCaller() + " · " + status.getComplied() + " have made it");
				callPanel.add(meta);
				callPanel.add(Box.createVerticalStrut(4));

				for (String name : status.getOnTile())
				{
					callPanel.add(buildCallRow(name, "on tile", ColorScheme.PROGRESS_COMPLETE_COLOR));
					callPanel.add(Box.createVerticalStrut(4));
				}
				for (String name : status.getOffTile())
				{
					callPanel.add(buildCallRow(name, "off", ColorScheme.PROGRESS_ERROR_COLOR));
					callPanel.add(Box.createVerticalStrut(4));
				}
			}

			callPanel.revalidate();
			callPanel.repaint();
		});
	}

	private JPanel buildCallRow(String name, String state, Color color)
	{
		final JPanel row = new JPanel(new GridLayout(1, 2));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JLabel nameLabel = new JLabel(name);
		nameLabel.setForeground(Color.WHITE);
		row.add(nameLabel);

		final JLabel stateLabel = new JLabel(state, JLabel.RIGHT);
		stateLabel.setForeground(color);
		row.add(stateLabel);
		return row;
	}

	// ---- Gear check (live) ----

	void updateGear(List<GearFlag> flags)
	{
		SwingUtilities.invokeLater(() ->
		{
			gearHeader.setText(flags.isEmpty()
				? "GEAR CHECK"
				: "GEAR CHECK (" + flags.size() + ")");

			gearPanel.removeAll();

			if (flags.isEmpty())
			{
				gearPanel.add(hint("Nobody nearby is flagged."));
			}
			else
			{
				for (GearFlag flag : flags)
				{
					gearPanel.add(buildGearRow(flag));
					gearPanel.add(Box.createVerticalStrut(4));
				}
			}

			gearPanel.revalidate();
			gearPanel.repaint();
		});
	}

	private JPanel buildGearRow(GearFlag flag)
	{
		final JPanel row = new JPanel(new GridLayout(1, 2));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JLabel name = new JLabel(flag.getDisplayName());
		name.setForeground(Color.WHITE);
		row.add(name);

		final JLabel warning = new JLabel(flag.getWarning(), JLabel.RIGHT);
		warning.setForeground(flag.isNaked()
			? ColorScheme.PROGRESS_ERROR_COLOR
			: ColorScheme.BRAND_ORANGE);
		row.add(warning);

		row.setToolTipText(flag.getDisplayName() + " — " + flag.getWarning()
			+ " (visible equipment only)");
		return row;
	}

	// ---- DD compliance (history) ----

	void update(List<PlayerStats> stats, boolean tileSet)
	{
		SwingUtilities.invokeLater(() ->
		{
			statusLabel.setText(tileSet
				? "DD tile: set"
				: "DD tile: not set (Shift + right-click a tile)");

			listPanel.removeAll();

			if (stats.isEmpty())
			{
				listPanel.add(hint("No calls tracked yet."));
			}
			else
			{
				stats.sort(Comparator
					.comparingInt(PlayerStats::getMissed).reversed()
					.thenComparing(PlayerStats::getCompliancePct)
					.thenComparing(PlayerStats::getDisplayName, String.CASE_INSENSITIVE_ORDER));

				for (PlayerStats ps : stats)
				{
					listPanel.add(buildRow(ps));
					listPanel.add(Box.createVerticalStrut(4));
				}
			}

			listPanel.revalidate();
			listPanel.repaint();
		});
	}

	private JLabel hint(String text)
	{
		final JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private JPanel buildRow(PlayerStats ps)
	{
		final JPanel row = new JPanel(new GridLayout(1, 2));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JLabel name = new JLabel(ps.getDisplayName());
		name.setForeground(Color.WHITE);
		row.add(name);

		final int pct = ps.getCompliancePct();
		final JLabel score = new JLabel(
			ps.getDdCount() + "/" + ps.getCallsSeen() + "  (" + pct + "%)",
			JLabel.RIGHT);
		if (pct >= 80)
		{
			score.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
		}
		else if (pct >= 50)
		{
			score.setForeground(ColorScheme.PROGRESS_INPROGRESS_COLOR);
		}
		else
		{
			score.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		}
		row.add(score);

		row.setToolTipText(ps.getDisplayName() + " — DD'd " + ps.getDdCount()
			+ " of " + ps.getCallsSeen() + " calls, missed " + ps.getMissed());
		return row;
	}
}

package com.ddtracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Flashes the prayer tab icon and shows a banner when someone calls a protection prayer.
 * Drawn above widgets so it is visible on top of the inventory/tab area.
 */
public class DdPrayerOverlay extends Overlay
{
	private static final int[] PRAYER_ICON_IDS = {
		ComponentID.FIXED_VIEWPORT_PRAYER_ICON,
		ComponentID.RESIZABLE_VIEWPORT_PRAYER_ICON,
		ComponentID.RESIZABLE_VIEWPORT_BOTTOM_LINE_PRAYER_ICON
	};

	private static final int[] PRAYER_TAB_IDS = {
		ComponentID.FIXED_VIEWPORT_PRAYER_TAB,
		ComponentID.RESIZABLE_VIEWPORT_PRAYER_TAB,
		ComponentID.RESIZABLE_VIEWPORT_BOTTOM_LINE_PRAYER_TAB
	};

	private final Client client;
	private final DdTrackerPlugin plugin;
	private final DdTrackerConfig config;

	@Inject
	private DdPrayerOverlay(Client client, DdTrackerPlugin plugin, DdTrackerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final String label = plugin.getPrayerAlertLabel();
		if (label == null)
		{
			return null;
		}

		final Rectangle bounds = findPrayerIconBounds();
		if (bounds == null)
		{
			return null;
		}

		// Pulse so it is hard to miss without being a solid block of color
		final double phase = (System.currentTimeMillis() % 1000) / 1000.0;
		final int alpha = (int) (110 + 110 * Math.abs(Math.sin(phase * Math.PI)));
		final Color base = config.prayerAlertColor();
		final Color pulse = new Color(base.getRed(), base.getGreen(), base.getBlue(),
			Math.min(255, alpha));

		final Rectangle box = new Rectangle(bounds.x - 2, bounds.y - 2,
			bounds.width + 4, bounds.height + 4);

		graphics.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), 55));
		graphics.fill(box);
		graphics.setColor(pulse);
		graphics.draw(box);

		drawLabel(graphics, label, box, base);
		return null;
	}

	private void drawLabel(Graphics2D graphics, String label, Rectangle box, Color color)
	{
		final Font original = graphics.getFont();
		graphics.setFont(original.deriveFont(Font.BOLD, 14f));
		final FontMetrics fm = graphics.getFontMetrics();
		final int w = fm.stringWidth(label);

		int x = box.x + box.width / 2 - w / 2;
		int y = box.y - 6;

		// Keep the banner on screen
		x = Math.max(4, Math.min(x, client.getCanvasWidth() - w - 4));
		y = Math.max(fm.getAscent() + 2, y);

		graphics.setColor(new Color(0, 0, 0, 190));
		graphics.fillRect(x - 4, y - fm.getAscent() - 2, w + 8, fm.getHeight() + 4);
		graphics.setColor(Color.BLACK);
		graphics.drawString(label, x + 1, y + 1);
		graphics.setColor(color);
		graphics.drawString(label, x, y);
		graphics.setFont(original);
	}

	private Rectangle findPrayerIconBounds()
	{
		Rectangle r = firstVisibleBounds(PRAYER_ICON_IDS);
		if (r == null)
		{
			r = firstVisibleBounds(PRAYER_TAB_IDS);
		}
		return r;
	}

	private Rectangle firstVisibleBounds(int[] componentIds)
	{
		for (int id : componentIds)
		{
			final Widget w = client.getWidget(id);
			if (w != null && !w.isHidden())
			{
				final Rectangle b = w.getBounds();
				if (b != null && b.width > 0 && b.height > 0)
				{
					return b;
				}
			}
		}
		return null;
	}
}

package com.ddtracker;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public class PlayerStats
{
	private final String displayName;
	private int callsSeen;
	private int ddCount;
	private boolean lastComplied;

	void record(boolean complied)
	{
		callsSeen++;
		lastComplied = complied;
		if (complied)
		{
			ddCount++;
		}
	}

	public int getMissed()
	{
		return callsSeen - ddCount;
	}

	/** Immutable-enough copy for handing to the Swing thread. */
	PlayerStats copy()
	{
		final PlayerStats c = new PlayerStats(displayName);
		c.callsSeen = callsSeen;
		c.ddCount = ddCount;
		c.lastComplied = lastComplied;
		return c;
	}

	public int getCompliancePct()
	{
		return callsSeen == 0 ? 100 : Math.round(100f * ddCount / callsSeen);
	}
}

